INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Darf ein Arbeitgeber gemäß § 14 Abs. 2 BBiG die Ausbildungsmaßnahmen frei auswählen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG gibt dem Arbeitgeber dieses Recht"}, {"text": "Nein", "correct": false, "because": "Auswahl ist gesetzlich erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Arbeitgeber bei der Auswahl der Ausbildungsmaßnahmen die Zustimmung des Auszubildenden einholen?', 2, '[{"text": "Ja", "correct": false, "because": "Das Weisungsrecht nach § 14 Abs. 2 BBiG erfordert keine Zustimmung"}, {"text": "Nein", "correct": true, "because": "Arbeitgeber hat Entscheidungsfreiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Arbeitgeber die Ausbildungsmaßnahmen an betriebliche Bedürfnisse anpassen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 2 BBiG erlaubt Anpassung im Rahmen der Ausbildung"}, {"text": "Nein", "correct": false, "because": "Betriebliche Bedürfnisse dürfen berücksichtigt werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Arbeitgeber verpflichtet, die Ausbildungsmaßnahmen mit der Berufsschule abzustimmen?', 2, '[{"text": "Ja", "correct": false, "because": "§ 14 Abs. 2 BBiG sieht keine Abstimmungspflicht vor"}, {"text": "Nein", "correct": true, "because": "Arbeitgeber hat freie Auswahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Arbeitgeber die Auswahl der Ausbildungsmaßnahmen nutzen, um praktische Tätigkeiten festzulegen?', 2, '[{"text": "Ja", "correct": true, "because": "Praktische Tätigkeiten sind Teil der Ausbildung (§ 14 Abs. 2 BBiG)"}, {"text": "Nein", "correct": false, "because": "Festlegung ist erlaubt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz gibt dem Arbeitgeber das Recht zur Auswahl der Ausbildungsmaßnahmen?', 2, '[{"text": "§ 14 Abs. 2 BBiG", "correct": true, "because": "Regelt das Weisungsrecht des Arbeitgebers"}, {"text": "§ 13 BBiG", "correct": false, "because": "Regelt Pflichten der Auszubildenden"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Arbeitgeber gemäß § 14 Abs. 2 BBiG bei der Auswahl der Ausbildungsmaßnahmen bestimmen?', 3, '[{"text": "Art und Umfang der praktischen Tätigkeiten", "correct": true, "because": "Teil des Weisungsrechts"}, {"text": "Die Berufsschulzeiten", "correct": false, "because": "Nicht in seiner Macht"}, {"text": "Die Prüfungsinhalte", "correct": false, "because": "Von der IHK festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer hat die Entscheidungsgewalt über die Auswahl der Ausbildungsmaßnahmen?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "§ 14 Abs. 2 BBiG gibt ihm dieses Recht"}, {"text": "Der Auszubildende", "correct": false, "because": "Kein Mitspracherecht"}, {"text": "Die Berufsschule", "correct": false, "because": "Keine Zuständigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkung gilt für die Auswahl der Ausbildungsmaßnahmen?', 3, '[{"text": "Sie müssen dem Ausbildungsziel dienen", "correct": true, "because": "§ 14 Abs. 2 BBiG setzt das Ziel voraus"}, {"text": "Sie müssen von der IHK genehmigt werden", "correct": false, "because": "Keine Genehmigung nötig"}, {"text": "Sie dürfen nur theoretisch sein", "correct": false, "because": "Praxis ist erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil hat der Arbeitgeber durch das Recht zur Auswahl der Ausbildungsmaßnahmen?', 3, '[{"text": "Flexibilität bei der Anpassung an betriebliche Bedürfnisse", "correct": true, "because": "§ 14 Abs. 2 BBiG ermöglicht dies"}, {"text": "Weniger Verantwortung", "correct": false, "because": "Verantwortung bleibt"}, {"text": "Kürzere Ausbildungszeit", "correct": false, "because": "Zeit unbeeinflusst"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Arbeitgeber bei der Auswahl der Ausbildungsmaßnahmen gemäß § 14 Abs. 2 BBiG?', 4, '[{"text": "Festlegung praktischer Tätigkeiten", "correct": true, "because": "Teil des Weisungsrechts"}, {"text": "Anpassung an betriebliche Abläufe", "correct": true, "because": "Erlaubt im Rahmen der Ausbildung"}, {"text": "Änderung der Berufsschulinhalte", "correct": false, "because": "Nicht in seiner Macht"}, {"text": "Entscheidung über Einsatzorte", "correct": true, "because": "Teil der Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte kann ein Arbeitgeber bei der Auswahl der Ausbildungsmaßnahmen berücksichtigen?', 3, '[{"text": "Betriebliche Anforderungen", "correct": true, "because": "§ 14 Abs. 2 BBiG erlaubt dies"}, {"text": "Fähigkeiten des Auszubildenden", "correct": true, "because": "Kann einfließen"}, {"text": "Wünsche der Berufsschule", "correct": false, "because": "Keine Pflicht"}, {"text": "Ausbildungsrahmenplan", "correct": true, "because": "Dient als Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Arbeitgeber gemäß § 14 Abs. 2 BBiG nicht tun?', 4, '[{"text": "Ausbildungsmaßnahmen frei wählen", "correct": false, "because": "Das darf er"}, {"text": "Den Auszubildenden einsetzen", "correct": false, "because": "Ist erlaubt"}, {"text": "Die Ausbildung vernachlässigen", "correct": true, "because": "Ausbildungsziel muss erfüllt werden"}, {"text": "Die Prüfungen verschieben", "correct": true, "because": "Liegt nicht in seiner Macht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat ein Arbeitgeber durch das Recht zur Auswahl der Ausbildungsmaßnahmen?', 3, '[{"text": "Kontrolle über die Ausbildung", "correct": true, "because": "Er bestimmt Inhalte"}, {"text": "Anpassung an betriebliche Prozesse", "correct": true, "because": "Flexibilität gegeben"}, {"text": "Weniger Kosten", "correct": false, "because": "Kosten nicht direkt beeinflusst"}, {"text": "Gestaltung praktischer Inhalte", "correct": true, "because": "Liegt in seinem Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen unterstützen die Auswahl der Ausbildungsmaßnahmen?', 3, '[{"text": "§ 14 Abs. 2 BBiG", "correct": true, "because": "Regelt das Recht des Arbeitgebers"}, {"text": "§ 11 BBiG", "correct": true, "because": "Regelt den Ausbildungsplan"}, {"text": "KSchG", "correct": false, "because": "Regelt Kündigungsschutz"}, {"text": "§ 13 BBiG", "correct": false, "because": "Regelt Pflichten der Auszubildenden"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Arbeitgeber darf die Ausbildungsmaßnahmen frei wählen. b) Er muss sie mit dem Auszubildenden abstimmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) § 14 Abs. 2 BBiG, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 14 Abs. 2 BBiG gibt dem Arbeitgeber das Recht zur Auswahl. b) Er darf betriebliche Bedürfnisse ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Arbeitgeber kann praktische Tätigkeiten festlegen. b) Die Auswahl muss das Ausbildungsziel fördern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) und b) § 14 Abs. 2 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Arbeitgeber darf die Berufsschulzeiten bestimmen. b) Er hat Flexibilität bei der Auswahl.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "b) § 14 Abs. 2 BBiG"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Arbeitgeber hat das Recht, Maßnahmen anzupassen. b) Er darf die Ausbildung komplett ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
